&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;R&#232;gles mythiques&lt;a class=&quot;headeranchor&quot; id=&quot;R&#232;gles_mythiques_0&quot; href=&quot;#R&#232;gles_mythiques_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;
